{
  "field_accounts": {
    "Q106C": {
      "account": "Interviewer-side record of whether community or party representatives approached the respondent. The wording 'Were you approached by community and/or political party representatives?' is addressed to the respondent but the metadata-native notes flag it as an ordinal f8.0 indicator with no explicit interviewer tag. It expresses a reported contact event, not a respondent-level attitude.",
      "quote": "Were you approached by community and/or political party representatives?"
    },
    "Q106D": {
      "account": "Reports a felt threat during the interview. The stem 'Did you feel threatened during the interview?' is phrased in first person, so it encodes respondent-side affect rather than an interviewer action.",
      "quote": "Did you feel threatened during the interview?"
    },
    "Q106E": {
      "account": "Reports physical threat during the interview. 'Were you physically threatened during the interview?' is a yes/no event indicator distinguishing non-physical threat (Q106D) from physical threat.",
      "quote": "Were you physically threatened during the interview?"
    },
    "Q109F": {
      "account": "Interviewer judgment of respondent demeanor: 'What was the respondent's attitude toward you' explicitly frames the item as an interviewer-side assessment on a three-point 'Honest | In between | Misleading' scale.",
      "quote": "What was the respondent's attitude toward you during the interview?"
    }
  },
  "rival_readings": [
    {
      "reading": "Q106C as respondent-reported approach",
      "support": "The second-person stem 'Were you approached' frames it as respondent experience, supporting a respondent-side reading.",
      "quote": "Were you approached"
    },
    {
      "reading": "Q106C as an interviewer-relayed contact indicator",
      "support": "The note 'Source-native SAV metadata reconciled to official merged codebook' treats it as a coded administrative indicator with no respondent-level depth.",
      "quote": "Source-native SAV metadata reconciled to official merged codebook"
    },
    {
      "reading": "Q106D and Q106E as overlapping threat measures",
      "support": "Both use 'during the interview' and the same binary '0 = No | 1 = Yes' scale, so they may read as a single threat construct split into felt vs physical.",
      "quote": "0 = No | 1 = Yes"
    }
  ],
  "surviving_positive": [
    "All four fields ship as ordinal numeric indicators with explicit value labels, so each has a determinate coding frame.",
    "Q109F provides a three-level demeanor ordinal '1 = Honest | 2 = In between | 3 = Misleading' that is distinct in wording from the binary Q106 items.",
    "Q106C is the only field naming external actors 'community and/or political party representatives'."
  ],
  "exact_discriminants": [
    {
      "discriminant": "Q106C vs Q106D/Q106E subject",
      "detail": "Q106C indexes external approach by representatives; Q106D and Q106E index felt and physical threat. The stems separate these: 'Were you approached' vs 'Did you feel threatened'.",
      "quote": "Did you feel threatened"
    },
    {
      "discriminant": "Q106D vs Q106E threat type",
      "detail": "The added adverb 'physically' in Q106E splits general threat from physical threat.",
      "quote": "Were you physically threatened"
    },
    {
      "discriminant": "Q109F response architecture",
      "detail": "Q109F is a three-category demeanor scale, unlike the binary items; options are '1 = Honest | 2 = In between | 3 = Misleading'.",
      "quote": "2 = In between"
    }
  ],
  "limits": [
    "Metadata only: no respondent-level co-occurrence among Q106C, Q106D, Q106E, and Q109F can be inferred.",
    "No causal relation between approach (Q106C) and threat (Q106D/Q106E) is observable from these rows.",
    "Actual administration and routing, including whether Q106D and Q106E were asked to everyone, are not stated.",
    "Missing routing cannot be derived; absence of a value is not evidence of non-administration.",
    "Interviewer-side coding of Q109F is preserved as interviewer-reported, not respondent experience."
  ],
  "foil_transfer_check": {
    "status": "held",
    "note": "A foil might claim approach caused felt threat or that Q106D/Q106E capture interviewer fear. Neither is supported: the stems use 'you' addressing the respondent (\"Did you feel threatened\"), and Q109F is the only item explicitly interviewer-judged (\"the respondent's attitude toward you\"). No co-occurrence or causal link is asserted.",
    "quote": "the respondent's attitude toward you"
  }
}
